hooks.command:
cd "$CLAUDE_PROJECT_DIR" && python3 -c "
import json, os, sys
files = ['default.json','package.json','.github/release-please-config.json','.github/.release-please-manifest.json']
errors = []
for f in files:
  if not os.path.exists(f): continue
  try: json.load(open(f))
  except Exception as e: errors.append(f'FAIL {f}: {e}')
if errors:
  print(json.dumps({'systemMessage': 'JSON syntax error: ' + '; '.join(errors)}))
  sys.exit(0)
try:
  pkg = json.load(open('package.json'))['version']
  manifest = json.load(open('.github/.release-please-manifest.json'))['.']
  if pkg != manifest:
    print(json.dumps({'systemMessage': f'Version mismatch: package.json={pkg} manifest={manifest}'}))
except: pass
"
